s='''def transform(grid):
    out = [row[:] for row in grid]
    R, C = len(grid), len(grid[0])
    # Identify 2-0-2 patterns on a row; color the gap and any aligned vertical
    # continuation below the center.
    for r in range(R):
        for c in range(1, C-1):
            if grid[r][c] == 0 and grid[r][c-1] == 2 and grid[r][c+1] == 2:
                out[r][c] = 1
                rr = r+1
                while rr < R and grid[rr][c] == 2:
                    break
                # The motif marks a horizontal segment extending between the
                # outer endpoints, plus a downward stem from the right endpoint.
                for x in range(c+1, C):
                    if grid[r][x] == 2:
                        break
                    if grid[r][x] == 0:
                        out[r][x] = 1
                # stem is located at right endpoint's column
                x = c+1
                while x < C and grid[r][x] != 2:
                    x += 1
                if x < C:
                    y = r+1
                    while y < R and grid[y][x] == 0:
                        # only color a one-cell vertical continuation where
                        # neighboring pattern support establishes the stem
                        if any(grid[y][z] == 2 for z in (x-1, x+1) if 0 <= z < C):
                            out[y][x] = 1
                        else:
                            break
                        y += 1
    return out
'''
