 "content": "def transform(grid):
    out = [row[:] for row in grid]
    R, C = len(grid), len(grid[0])
    # Find the diamond (four 2s around an empty center); extend its internal
    # arms toward its center, then along the rows/column connecting motifs.
    diamonds = []
    for r in range(1, R-1):
        for c in range(1, C-1):
            if grid[r][c-1] == 2 and grid[r][c+1] == 2 and grid[r-1][c] == 2 and grid[r+1][c] == 2:
                diamonds.append((r, c))
                out[r][c] = 1
    # Color zero cells within a 2-by-2 connection network of diamond points:
    # spans on rows connecting paired side arms and vertical gaps between tips.
    if len(diamonds) >= 2:
        rows = sorted(set(r for r,c in diamonds))
        cols = sorted(set(c for r,c in diamonds))
        for r in rows:
            centers = sorted(c for rr,c in diamonds if rr == r)
            if len(centers) >= 2:
                for x in range(centers[0]+2, centers[-1]-1):
                    if grid[r][x] == 0: out[r][x] = 1
        for c in cols:
            cr = sorted(r for r,cc in diamonds if cc == c)
            if len(cr) >= 2:
                for y in range(cr[0]+2, cr[-1]-1):
                    if grid[y][c] == 0: out[y][c] = 1
    # The lower-center diamond's right tip reaches the nearby right-facing arm
    # where a matching flanking pair is present.
    for r in range(R):
        for c in range(1, C-1):
            if grid[r][c-1] == 2 and grid[r][c+1] == 2 and grid[r][c] == 0:
                # central gap is colored when both endpoints are part of the repeated motif
                if (r,c-1) in diamonds or (r,c+1) in diamonds:
                    out[r][c] = 1
    return out
