    R, C = len(grid), len(grid[0])
    # A 2-0-2 pair with a 2 directly above/below its center forms the
    # inward-pointing corner of a diamond. Color that center.
    for r in range(R):
        for c in range(1, C-1):
            if grid[r][c-1] == 2 and grid[r][c] == 0 and grid[r][c+1] == 2:
                if (r > 0 and grid[r-1][c] == 2) or (r+1 < R and grid[r+1][c] == 2):
                    out[r][c] = 1

    # Between adjacent inward-facing corners on the same row, fill the open
    # horizontal corridor, stopping before each corner's immediate endpoints.
    for r in range(R):
        corners = [c for c in range(1, C-1)
                   if grid[r][c-1] == 2 and grid[r][c+1] == 2 and
                   ((r > 0 and grid[r-1][c] == 2) or
                    (r+1 < R and grid[r+1][c] == 2))]
        if len(corners) >= 2:
            left, right = min(corners), max(corners)
            for c in range(left+2, right-1):
                if grid[r][c] == 0:
                    out[r][c] = 1

    # Aligned vertical tips also form a connecting stem; color its one-cell
    # gap if the middle row has a lateral 2, indicating a motif junction.
    for c in range(C):
        for r in range(1, R-1):
            if grid[r-1][c] == 2 and grid[r][c] == 0 and grid[r+1][c] == 2:
                if any(grid[r][x] == 2 for x in range(C)):
                    out[r][c] = 1
    return out
